import os
import tomllib
from typing import Any


class ConfigError(Exception):
    def __init__(self, key: str, expected: str, actual: str):
        self.key = key
        self.expected = expected
        self.actual = actual
        super().__init__(f"Invalid value for {key}: expected {expected}, got '{actual}'")


def _coerce(value: str, expected_type: type) -> Any:
    if expected_type is int:
        try:
            return int(value)
        except ValueError:
            raise ConfigError("int", "int", value)
    if expected_type is float:
        try:
            return float(value)
        except ValueError:
            raise ConfigError("float", "float", value)
    if expected_type is bool:
        lower = value.lower()
        if lower in ("true", "1", "yes"):
            return True
        if lower in ("false", "0", "no"):
            return False
        raise ConfigError("bool", "bool", value)
    if expected_type is str:
        return value
    raise ConfigError("unknown", str(expected_type), value)


